type TagFilters = { tech: string[]; 'work-type': string[] }
const EMPTY_TAG_FILTERS: TagFilters = { tech: [], 'work-type': [] }

function nodeMatchesTags(node: { tags?: { tech: string[]; domain?: string[]; 'work-type': string[] } }, filters: TagFilters): boolean {
  const tg = node.tags || { tech: [], 'work-type': [] }
  if (filters.tech.length && !filters.tech.some(v => tg.tech.includes(v))) return false
  if (filters['work-type'].length && !filters['work-type'].some(v => tg['work-type'].includes(v))) return false
  return true
}

function hasActiveTagFilters(f: TagFilters) {
  return f.tech.length > 0 || f['work-type'].length > 0
}

function hasAnyFilter(f: TagFilters, squads: string[]) {
  return hasActiveTagFilters(f) || squads.length > 0
}

